/// v0.8.52 (owner fix 3): Up/Down = current ± one grid ROW, ONLY while the dock is open.
/// The rig registers on_sel_jump and drives real key events through the window: with the
/// dock closed the arrows fall through to key-typed (their pre-existing route — they had
/// NO binding: the keys scope had no arm and ACTIONS binds letters only); open, they jump
/// by the live column count, clamped at both folder ends.
#[test]
fn grid_arrow_keys_row_jump() {
    let app = boot();
    let jumped: std::rc::Rc<std::cell::Cell<i32>> = std::rc::Rc::new(std::cell::Cell::new(-1));
    let j = jumped.clone();
    app.on_sel_jump(move |i| j.set(i));
    app.set_count_all(20);
    app.set_cur_idx(7);
    app.set_grid_cols(3);
    key(&app, slint::platform::Key::DownArrow);
    assert_eq!(jumped.get(), -1, "dock closed: Down must NOT row-jump (falls through as before)");
    app.set_grid_open(true);
    key(&app, slint::platform::Key::DownArrow);
    assert_eq!(jumped.get(), 10, "Down = current + cols");
    key(&app, slint::platform::Key::UpArrow);
    assert_eq!(jumped.get(), 4, "Up = current − cols (cur-idx pinned at 7 — the rig runs no tick)");
    app.set_cur_idx(1);
    key(&app, slint::platform::Key::UpArrow);
    assert_eq!(jumped.get(), 0, "clamped at the folder start");
    app.set_cur_idx(18);
    key(&app, slint::platform::Key::DownArrow);
    assert_eq!(jumped.get(), 19, "clamped at the folder end");
    app.set_grid_open(false);
}

/// v0.8.160 (B1/U8, OWNER RULING 1's own parity note): **`current` DOES NOT MOVE UNDER AN OPEN
/// MENU.**
///
/// D1a gated the three photo WHEELS on `popup-open`; every NAV KEY arm kept `!modal-open`, which
/// contains none of the popup surfaces (six when this was written; five since v0.8.192 retired the
/// title-bar path menu). So a right-click menu — which captures its target index
/// when it opens — could have the current shot walked out from under it by Home / End / the arrows /
/// compare's Tab and Space, which is the frozen-menu case D1b was written to apologise for. The
/// predicate already existed and the comment beside the wheel gates already promised nav parity;
/// this is that promise, kept.
///
/// The DIFFERENTIAL is the whole test: every arm is driven with the popup OPEN and with it CLOSED,
/// so a gate so wide the keys never work fails just as loudly as no gate at all.
///
/// FALSIFIER (L28): revert any one nav arm to `!root.modal-open` and its own row reddens with a
/// dispatch that fired under an open menu; delete a term from `popup-open` and every arm reddens
/// for that surface alone.
#[test]
fn an_open_popup_pauses_the_nav_keys() {
    let app = boot();
    let hits: std::rc::Rc<std::cell::Cell<i32>> = std::rc::Rc::new(std::cell::Cell::new(0));
    let (j, n, s, p) = (hits.clone(), hits.clone(), hits.clone(), hits.clone());
    app.on_sel_jump(move |_| j.set(j.get() + 1));
    app.on_navigate(move |_| n.set(n.get() + 1));
    app.on_compare_set_active(move |_| s.set(s.get() + 1));
    app.on_compare_toggle_pin(move |_| p.set(p.get() + 1));
    app.set_count_all(20);
    app.set_cur_idx(7);
    app.set_grid_cols(3);
    app.set_grid_open(true); // Up/Down are dock-gated — mount their precondition
    app.set_compare(true); // …and Tab/Space are compare-gated

    use slint::platform::Key;
    let arms: [(&str, Key); 6] = [
        ("→ next", Key::RightArrow),
        ("← prev", Key::LeftArrow),
        ("Home", Key::Home),
        ("End", Key::End),
        ("↑ row", Key::UpArrow),
        ("↓ row", Key::DownArrow),
    ];
    // Tab and Space are typed as text tokens, not named keys, on this scope's compare arms.
    let taps = |a: &ui::MainWindow| {
        for (_, k) in arms {
            key(a, k);
        }
        key(a, Key::Tab);
        key(a, Key::Space);
    };

    // BASELINE: nothing open, every arm dispatches.
    hits.set(0);
    taps(&app);
    let free = hits.get();
    assert!(free >= 8, "baseline: all eight nav arms must dispatch with nothing open (got {free})");

    // v0.8.192: five, not six — "path-ctx-open" retired with the title-bar path menu.
    let names = ["ctx-open", "sel-ctx-open", "sort-open", "open-menu-open", "notif-open"];
    let set_flag = |a: &ui::MainWindow, i: usize, v: bool| match i {
        0 => a.set_ctx_open(v),
        1 => a.set_sel_ctx_open(v),
        2 => a.set_sort_open(v),
        3 => a.set_open_menu_open(v),
        4 => a.set_notif_open(v),
        _ => unreachable!(),
    };
    for (i, name) in names.iter().enumerate() {
        set_flag(&app, i, true);
        i_slint_core::properties::ChangeTracker::run_change_handlers();
        assert!(app.get_popup_open(), "{name} must raise the shared popup predicate");
        hits.set(0);
        taps(&app);
        assert_eq!(
            hits.get(),
            0,
            "{name}: a nav key moved `current` under an open popup — the menu's captured target is \
             now a photograph the reader is no longer looking at"
        );
        set_flag(&app, i, false);
        i_slint_core::properties::ChangeTracker::run_change_handlers();
    }

    // …and closing them gives every arm back (the gate is not a latch).
    hits.set(0);
    taps(&app);
    assert_eq!(hits.get(), free, "closed again: the nav keys work exactly as before");
    app.set_compare(false);
    app.set_grid_open(false);
}

/// v0.8.50 (G2): the grid splitter, end-to-end — drag the 5px lane on the stage's
/// left edge and the dock SNAPS to whole columns: left past the 2-column point →
/// exactly 264 (2 cols); far right → capped at ⌊1200/3⌋-fitting 3 columns = 392.
#[test]
fn grid_splitter_drags_snap_to_whole_columns() {
    use i_slint_core::input::MouseEvent;
    use i_slint_core::items::PointerEventButton;
    use i_slint_core::lengths::LogicalPoint;
    let app = boot();
    app.set_grid_open(true);
    hover(&app, 600.0, 300.0);
    assert_eq!(app.get_grid_dock_w(), 392.0, "the persisted default = 3 columns");
    let drag = |from: (f32, f32), to: (f32, f32)| {
        let w = i_slint_core::window::WindowInner::from_pub(app.window());
        w.process_mouse_input(MouseEvent::Pressed {
            position: LogicalPoint::new(from.0, from.1),
            button: PointerEventButton::Left,
            click_count: 1,
            touch_finger_id: 0,
        });
        w.process_mouse_input(MouseEvent::Moved {
            position: LogicalPoint::new(to.0, to.1),
            touch_finger_id: 0,
        });
        w.process_mouse_input(MouseEvent::Released {
            position: LogicalPoint::new(to.0, to.1),
            button: PointerEventButton::Left,
            click_count: 1,
            touch_finger_id: 0,
        });
        i_slint_core::properties::ChangeTracker::run_change_handlers();
    };
    // the splitter lane = stage x 0..5 = window x 392..397 while the dock is 392
    drag((394.0, 400.0), (300.0, 400.0));
    assert_eq!(app.get_grid_dock_w(), 264.0, "drag left snaps to exactly 2 columns");
    drag((266.0, 400.0), (900.0, 400.0));
    assert_eq!(app.get_grid_dock_w(), 392.0, "drag right caps at 3 columns (the 1200/3 cap)");
    app.set_grid_open(false);
}

/// The bell (Fix 3) sits in the right cluster, flush to the right edge. v0.8.180: the
/// bell is a bar-wash button and narrowed 44→40 with the true-square ruling (the caption
/// trio behind it stays 44 — Windows convention), so the cluster is 40 + 3×44 = 172 and
/// the bell's centre is width − 172 + 20 = width − 152. Regression-pins the right-edge
/// host AND the 3px clamp maths of the tiplayer (cx − w/2 vs width − w − 3).
#[test]
fn tip_cx_matches_bell_centre() {
    let app = boot();
    let centre = 1200.0 - (40.0 + 3.0 * 44.0) + 20.0; // first right-cluster cell = the bell (40px)
    hover(&app, centre, 22.0);
    let tip = app.global::<ui::Tip>();
    assert_eq!(tip.get_text(), "Notifications", "the bell reports its tip");
    let cx = tip.get_cx();
    assert!(
        (cx - centre).abs() < 0.5,
        "bell: reported cx {cx} != true centre {centre} (drift {})",
        cx - centre
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// v0.9.11 (native traffic lights): the macOS title-bar arm, measured on the rig.
// native-window-controls + titlebar-leading-inset default to the WINDOWS values
// (false / 0px) — every other test in this file runs the bar at those defaults,
// so the existing suite (button centres at 44·i+22, the bell at width−4·44+22,
// the HUD frames, the path-pill tiers) IS the Windows byte-identity pin. This
// test flips the two properties to the macOS boot values (main.rs) and asserts
// the three .slint effects: the left cluster shifts right by the inset, the
// inset zone itself hosts NO Falcon hover target (the native lights above must
// win it), and the custom min/max/close cluster unmounts (the bell becomes the
// LAST right-cluster cell).
// v0.9.59 (S3): the 80px pinned here is now ALSO the clamp the AppKit-side
// traffic-light shift reads (support::traffic_light_dx, fed the live
// titlebar-leading-inset property by both center_traffic_lights call sites) —
// the lights are placed so that cluster-right + 8px stays inside this inset.
// The round moved the AppKit x positions only, so the Slint pin is unchanged;
// if a later round grows the inset, BOTH this pin and the clamp move with it
// automatically because they read the one property.
// ─────────────────────────────────────────────────────────────────────────────
#[test]
fn native_window_controls_shift_cluster_and_inert_inset() {
    let app = boot();
    app.set_native_window_controls(true);
    app.set_titlebar_leading_inset(80.0);
    // Left cluster: the Settings cell now spans 80..124 — centre 102.
    hover(&app, 102.0, 22.0);
    let tip = app.global::<ui::Tip>();
    assert_eq!(tip.get_text(), "Settings", "left cluster shifts right by the 80px inset");
    assert!((tip.get_cx() - 102.0).abs() < 0.5, "cx {} != shifted centre 102", tip.get_cx());
    // The inset (traffic-light) zone is inert chrome: no tip may latch there.
    hover(&app, 600.0, 400.0); // clear the latch off-bar first
    hover(&app, 40.0, 22.0);
    assert_eq!(tip.get_text(), "", "no Falcon hover target under the lights");
    // Right cluster: min/max/close are unmounted — the bell is the last cell, and v1.0 MERGE
    // (F1-1's own arithmetic) it is a 40 px one: trunk's v0.8.180 ruling narrowed every
    // bar-wash button. The hover below is comfortably inside either, which is exactly why the
    // EDGE row beside this one exists.
    hover(&app, 1200.0 - 22.0, 22.0);
    assert_eq!(tip.get_text(), "Notifications", "bell sits flush right once min/max/close unmount");
    // Flip back to the Windows values: the original geometry returns LIVE (belt-and-
    // braces beyond the boot defaults the rest of the suite pins).
    app.set_native_window_controls(false);
    app.set_titlebar_leading_inset(0.0);
    hover(&app, 22.0, 22.0);
    assert_eq!(tip.get_text(), "Settings", "Windows geometry restored at the defaults");
}

// ─────────────────────────────────────────────────────────────────────────────
// v0.9.59 (OWNER RULINGS 08-02 / C3): the two title-bar COMPOSITION rulings.
// S4a — the title/path HUD group centres on the WINDOW, not on the free band
// (findings §C-2: band-centring put it W/2 + 159px right of centre on macOS).
// S4b — the cache meter moves to the RIGHT group, immediately left of the bell,
// "so the left-right side is slightly more balanced"; Windows keeps both as is.
// Both are rig-measurable; the VISUAL result is tester-round-5 proof.
// ─────────────────────────────────────────────────────────────────────────────

/// Boot a bar with a full HUD cluster mounted (T1: chips + pill + meter) at `w` logical px.
fn hud_app(w: f32, mac: bool) -> ui::MainWindow {
    let app = boot();
    app.set_motion_ui(false);
    app.set_native_window_controls(mac);
    app.set_titlebar_leading_inset(if mac { 80.0 } else { 0.0 });
    app.set_count_all(65);
    app.set_count_picks(2);
    app.set_count_rejects(5);
    app.set_path_text("D:\\…\\2026Shoot\\101CANON\\HWU_7809.CR3".into());
    app.set_hud_pos("9/65".into());
    app.set_hud_pos_widest_a("00/65".into());
    app.set_hud_pos_widest_b("88/65".into());
    app.set_cache_meter_show(true);
    app.set_cache_len_before(0.5);
    app.set_cache_len_after(0.5);
    app.set_cache_frac_before(0.8);
    app.set_cache_frac_after(0.4);
    app.window().set_size(slint::LogicalSize::new(w, 800.0));
    hover(&app, w / 2.0, 300.0); // settle the layout the way the other bar tests do
    app
}

/// The HUD group's measured (left, width) in WINDOW space, from the row element itself.
fn hud_row(app: &ui::MainWindow) -> (f32, f32) {
    let e = i_slint_backend_testing::ElementHandle::find_by_element_id(app, "MainToolbar::hudrow")
        .next()
        .expect("the HUD row is mounted");
    (e.absolute_position().x, e.size().width)
}

/// v1.0 MERGE (F6-3) — **THE CLUSTER'S EDGES, NOT ITS CENTRES.**
///
/// `native_window_controls_shift_cluster_and_inert_inset` probes CENTRES: it hovers 102 and expects
/// "Settings", hovers 40 and expects nothing. Both survive a boundary that is one, two or four pixels
/// out of place — a 44 px first cell starting at 80 answers identically at its centre, and so does a
/// 40 px one starting at 78. F6-3's point is that the numbers this platform's layout is BUILT from
/// are boundaries, so a row has to measure boundaries.
///
/// The two that matter, and what each one is:
///   * x = 82 — where Falcon's first cell begins, which is the SUM `titlebar-leading-inset (80) +
///     padding-left (2)` that the Settings-centre pin depends on (F1-5 / owner default L2), read from
///     the other side. Note what that means: 80..82 is the 2 px window-edge lead-in and it is inert
///     chrome too, so this pair measures BOTH terms of the sum at once — drop the lead-in and the
///     boundary moves to 80, drop the inset and it moves to 2.
///   * x = W − 40 — where the bell cell begins, which is F1-1's own literal: the bell was a 44 px
///     cell when the branch's cache-meter row was written and is a 40 px one now.
///
/// FALSIFIER (L28): change `titlebar-leading-inset` to 78 or 82 and the first pair reddens; restore
/// any bar-wash button to `width: 44px` and the second pair does.
#[test]
fn mac_cluster_edges_are_where_the_arithmetic_says() {
    let app = boot();
    app.set_native_window_controls(true);
    app.set_titlebar_leading_inset(80.0);
    let tip = app.global::<ui::Tip>();
    let probe = |x: f32| -> String {
        hover(&app, 600.0, 400.0); // clear the latch off-bar between probes (the A→B hover rule)
        hover(&app, x, 22.0);
        tip.get_text().to_string()
    };
    // THE FIRST CELL'S LEADING EDGE, at inset 80 + lead-in 2 = 82. Inside the inset AND inside the
    // lead-in: inert chrome, no Falcon target at all. One pixel past the sum: Settings.
    assert_eq!(probe(79.0), "", "x=79 is the traffic-light zone");
    assert_eq!(probe(81.0), "", "x=81 is the 2 px window-edge lead-in — still not a target");
    assert_eq!(probe(83.0), "Settings", "x=83 is inside the first cell (80 + 2)");
    // THE BELL'S EDGES, with the trio unmounted. `boot()` sizes the window to 1200 (every row in
    // this battery's neighbourhood does). 2026-09-25 (owner, "Option 1 + 2 pt"): the bell no longer
    // sits flush against the window edge — a 2 px trailing lead-in mirrors the leading one — so its
    // 40 px cell spans W − 42 .. W − 2 and the last 2 px are inert chrome.
    let w = 1200.0_f32;
    assert_eq!(probe(w - 41.0), "Notifications", "the bell owns the 40 px cell before the 2 px lead-in");
    assert_ne!(
        probe(w - 43.0),
        "Notifications",
        "one pixel left of W−42 is NOT the bell — the cell would be 44 px wide"
    );
    assert_eq!(probe(w - 1.0), "", "the trailing 2 px lead-in is not a target");
}

/// v0.9.59 (S4a, OWNER RULING C3): on macOS the HUD group's CENTRE is the WINDOW's centre — not the
/// centre of the free band between the button groups, which is what §C-2 measured as 159px right of
/// centre (97px after S4b's rebalance). Windows is untouched: it keeps band-centring, the geometry
/// the whole v0.7.2 contract and the rest of this file pin.
/// FALSIFIER: delete the `root.native-window-controls ?` arm of `hudrow`'s x binding (i.e. keep
/// band-centring everywhere) — the macOS assert reddens by ~97px. Deleting only the CLAMP instead
/// reddens `hud_group_clamps_into_the_band_at_narrow_widths`.
#[test]
fn hud_group_centres_on_the_window_under_native_controls() {
    // A wide window: the window centre is comfortably inside the band, so the clamp is inert.
    let app = hud_app(1600.0, true);
    let (x, w) = hud_row(&app);
    let centre = x + w / 2.0;
    // ── v1.0 MERGE [A-2]: RE-DERIVED, because the row is on the even grid now. ─────────────
    // Trunk's v0.8.188 (L46) snap wraps this row's x on BOTH platforms — the ruling is that an
    // unsnapped row origin hands its half-pixel phase down to every mount below it, which is the
    // filmstrip-chip defect that round was about, and it is not a Windows-only fact. The branch's
    // window-centred offset is computed exactly as it was and THEN rounded to the even grid relative
    // to the band origin, so the achievable centre is the window centre plus a residual of at most
    // one logical pixel.
    //
    //   band x          = left-reserve 224 + the 80 px light inset            = 304
    //   ideal local x   = (1600 − w) / 2 − 304
    //   snapped local x = round(ideal / 2) × 2                                (the L46 snap)
    //   expected centre = 304 + snapped local x + w / 2
    //
    // At the measured row width (525 on this rig's metrics) that is 538 + 262.5 = 800.5. The 0.5 px
    // TOLERANCE STAYS, and it is applied to the DERIVED value rather than to a literal: a font-metric
    // change to the row's preferred width now moves the expectation with it instead of reddening this
    // row for a reason that has nothing to do with centring. The snap's own bound — the thing a
    // reader actually wants to know — is the second assert.
    let band_x = 224.0 + 80.0;
    let ideal = (1600.0 - w) / 2.0 - band_x;
    let expected = band_x + (ideal / 2.0).round() * 2.0 + w / 2.0;
    assert!(
        (centre - expected).abs() < 0.5,
        "mac: HUD centre {centre} != the snapped window centre {expected} (row x {x}, w {w})"
    );
    assert!(
        (centre - 800.0).abs() <= 1.0,
        "mac: the even-grid snap may cost at most 1 logical px of centring, not {} (centre {centre})",
        (centre - 800.0).abs()
    );
    assert_eq!(x % 2.0, 0.0, "mac: the row origin {x} is off the even grid the snap exists to hold");
    // The SAME window on Windows margins keeps the historic band-centring: band =
    // [286, 1600-180] → centre 853 = W/2 + 53, the long-standing (and deliberately unchanged)
    // Windows offset the findings doc names.
    let app = hud_app(1600.0, false);
    let (x, w) = hud_row(&app);
    let centre = x + w / 2.0;
    // v1.0 MERGE [A-2]: DERIVED THE SAME WAY, and it has to be. This row's 853 was measured on the
    // branch, where `hudrow`'s x was the raw band-centred offset; the snap now rounds it here too, so
    // the Windows arm reads 852.5 for exactly the reason the mac arm reads 800.5 — an odd row width
    // against an even grid. Pinning the literal would have made this row assert that Windows was NOT
    // snapped, which is the opposite of the L46 ruling it now lives under. The band is
    // [286, 1600 − 180] and its centre is 853; the residual bound is the assert that matters.
    //
    // NOTE THE DIFFERENT ARITHMETIC, which is the whole point of the platform split: the Windows arm
    // centres the row in the BAND (its own parent), the mac arm centres it on the WINDOW and clamps
    // into the band. Same snap, two ideals — so this expectation is built from the band width and
    // the one above is built from the window width.
    let band_x = 286.0;
    let band_w = 1600.0 - 286.0 - 180.0;
    let ideal = (band_w - w) / 2.0;
    let expected = band_x + (ideal / 2.0).round() * 2.0 + w / 2.0;
    assert!(
        (centre - expected).abs() < 0.5,
        "windows: HUD centre {centre} != the snapped band centre {expected} (row x {x}, w {w})"
    );
    assert!(
        (centre - 853.0).abs() <= 1.0,
        "windows: the band centre is 853 = W/2 + 53 and the snap may cost at most 1 px, not {}",
        (centre - 853.0).abs()
    );
    assert_eq!(x % 2.0, 0.0, "windows: the row origin {x} is off the even grid");
}

/// v0.9.59 (S4a): the clamp. Window-centring inside a CLIPPING frame is only safe if it degrades at
/// the edges — at narrow widths the window centre would push the group's left edge off the band (and
/// its right edge under the buttons), where hudclip.clip would simply cut it. So it pins to the band
/// edge instead, and never leaves the band.
/// FALSIFIER: drop the `clamp(...)` in `hudrow`'s x binding (return the raw window-centred offset) —
/// the "never negative" assert reddens with a negative x at the narrow width.
#[test]
fn hud_group_clamps_into_the_band_at_narrow_widths() {
    for w in [1600.0_f32, 1200.0, 1000.0, 900.0, 820.0] {
        let app = hud_app(w, true);
        let (x, gw) = hud_row(&app);
        // Band geometry under native controls: left 224 + 80 inset, right 110.
        let band_x = 224.0 + 80.0;
        let band_w = (w - 224.0 - 80.0 - 110.0).max(0.0);
        assert!(
            x >= band_x - 0.5,
            "w={w}: the group's left edge {x} escaped the band's left edge {band_x}"
        );
        assert!(
            x + gw <= band_x + band_w + 0.5,
            "w={w}: the group's right edge {} escaped the band's right edge {}",
            x + gw,
            band_x + band_w
        );
    }
}

/// v0.9.59 (S4b, OWNER RULING C3): the cache meter's ANCHOR. On macOS it is the last element before
/// the notification bell — its right edge meets the bell's cell, i.e. W − 40; on Windows it stays in
/// the left group, after the 2 px window-edge lead-in and the five 40 px buttons (x = 202). Exactly
/// ONE instance mounts in either mode (the two gates are mutually exclusive), so the shared
/// `cache-meter-cx` channel can never have two writers.
///
/// v1.0 MERGE TAIL [A-O1]: this header said "the bell's 44px cell, i.e. W − 44" and "the five 44px
/// buttons (x = 220)" — both disproved by the asserts underneath it, which the merge corrected and
/// this paragraph did not. Trunk's v0.8.180 owner ruling made every bar-wash button a 40×44 CELL
/// (40 wide) and added the 2 px lead-in; F1-1 is the whole reason this row was on the merge's list,
/// so a header still describing the world before it is the defect F1-1 is about, one level up.
/// FALSIFIER: swap the two call sites' `native-window-controls` gates in main_window.slint (i.e.
/// revert the anchor) — both position asserts redden, and the "exactly one instance" assert holds,
/// which is what makes the position asserts the real evidence.
#[test]
fn cache_meter_anchors_left_of_the_bell_on_mac_and_stays_left_on_windows() {
    let meter = |app: &ui::MainWindow| -> (usize, f32, f32) {
        let v: Vec<_> =
            i_slint_backend_testing::ElementHandle::find_by_element_type_name(app, "CacheMeter")
                .collect();
        let n = v.len();
        let e = v.first().expect("the cache meter is mounted");
        (n, e.absolute_position().x, e.size().width)
    };
    // macOS: [W−104, W−42] — flush against the bell cell.
    // v1.0 MERGE (F1-1): the bell was a 44 px cell when this row was written; trunk's v0.8.180
    // ruling narrowed every bar-wash button to a 40 px cell. 2026-09-25 (owner, "Option 1 + 2 pt"):
    // a 2 px trailing lead-in follows the bell, so the bell's left edge is W − 42.
    let app = hud_app(1600.0, true);
    let (n, x, w) = meter(&app);
    assert_eq!(n, 1, "exactly one meter instance mounts");
    assert!((w - 62.0).abs() < 0.5, "the meter keeps its 62px width, got {w}");
    assert!(
        (x + w - (1600.0 - 42.0)).abs() < 0.5,
        "mac: meter right edge {} != the bell's left edge {}",
        x + w,
        1600.0 - 42.0
    );
    // Windows: after the 2 px lead-in and the five 40 px buttons, with no traffic-light inset.
    let app = hud_app(1600.0, false);
    let (n, x, w) = meter(&app);
    assert_eq!(n, 1, "exactly one meter instance mounts");
    // v1.0 MERGE (F1-1): 220 was 5 × 44. Trunk's v0.8.180 owner ruling made the bar cells 40 px
    // wide and added a 2 px window-edge lead-in, so the meter now starts at 2 + 5×40 = 202.
    assert!((x - 202.0).abs() < 0.5, "windows: meter x {x} != 2 + 5×40 = 202");
    assert!((w - 62.0).abs() < 0.5);
}

/// v0.9.59 (S4b): the reservation arithmetic moved WITH the element, so the centre BAND keeps the
/// exact WIDTH it had before the meter changed sides (the 62px leaves the left reservation and
/// arrives in the right one) — which is why the T1/T2/T3 seams and `mac_native_controls_band_four_tiers`
/// did not have to move. Only the band's ORIGIN shifts, 62px left, which is the point of the move.
/// FALSIFIER: change hudclip's macOS `right-reserve` to 48px (the pre-S4b value) without touching
/// `left-reserve` — the band grows 62px and the width assert reddens (and, on the real bar, the
/// meter would sit under the group).
#[test]
fn mac_band_width_survives_the_meter_move() {
    let band = |app: &ui::MainWindow| -> (f32, f32) {
        let e = i_slint_backend_testing::ElementHandle::find_by_element_id(app, "MainToolbar::hudclip")
            .next()
            .expect("the HUD clip frame is mounted");
        (e.absolute_position().x, e.size().width)
    };
    // macOS: left 224 + the 80px light inset, right 110 → x 304, width W − 414 — the SAME width the
    // pre-S4b 286/inset/48 arithmetic produced.
    let app = hud_app(1600.0, true);
    let (x, w) = band(&app);
    assert!((x - 304.0).abs() < 0.5, "mac: band x {x} != 224 + 80");
    assert!((w - (1600.0 - 414.0)).abs() < 0.5, "mac: band width {w} != W − 414");
    assert!(
        (w - (1600.0 - 286.0 - 80.0 - 48.0)).abs() < 0.5,
        "the pre-move arithmetic gives the SAME width — that is why the tier seams stand"
    );
    // Windows: the v0.7.2 contract, byte-identical — 286 left, 180 right.
    let app = hud_app(1600.0, false);
    let (x, w) = band(&app);
    assert!((x - 286.0).abs() < 0.5, "windows: band x {x} != 286");
    assert!((w - (1600.0 - 466.0)).abs() < 0.5, "windows: band width {w} != W − 286 − 180");
}

