/// 2026-09-25 (owner: option 1 with "Option 1 + 2 pt"). The Mac title-bar toolbar is sized to
/// AppKit's measured title bar, 38 pt in the compact toolbar style. In full04-3 a 44 pt surface in
/// that 38 pt title bar lost its top 6 pt. At 38, every bar button is a 34 pt cell whose hover
/// square is 30×30 and centred on the bar's middle. The status chips centre there too. The bell's
/// badge keeps its place above the bell glyph, and the bell's cell ends 2 pt before the window
/// edge. At 44 the cells are the Windows 40 pt with 36 pt squares. The squares' 10 pt radius is a
/// formula on `barwash` (12 × side / 36, rounded to even) that the rig cannot read; the owner
/// judges it on the Mac.
/// FALSIFIER: restore `height: 44px` in MacToolbarWindow and every row at 38 fails. Restore
/// `width: 40px` on the bar buttons and the cell and square rows fail. Restore `y: 9px` on the
/// badge and the badge row fails. Restore `padding-right: 0px` and the edge row fails.
#[test]
fn mac_title_bar_toolbar_fits_the_measured_title_bar() {
    use i_slint_backend_testing::ElementHandle as E;
    let width = 1280.;
    let app = hud_app(width, true);
    app.set_notif_unread(1);
    let bar = ui::MacToolbarWindow::new().unwrap();
    bar.set_state(app.get_toolbar_state());
    bar.set_host_width(width);
    for (h, cell, side) in [(38.0f32, 34.0f32, 30.0f32), (44., 40., 36.)] {
        bar.set_host_height(h);
        i_slint_core::properties::ChangeTracker::run_change_handlers();
        let cells: Vec<_> = E::find_by_element_type_name(&bar, "IconBtn").collect();
        assert_eq!(cells.len(), 6, "five left buttons and the bell at h={h}");
        for c in &cells {
            assert_eq!(c.size(), slint::LogicalSize::new(cell, h), "bar button cell at h={h}");
        }
        let washes: Vec<_> = E::find_by_element_id(&bar, "IconBtn::barwash").collect();
        assert_eq!(washes.len(), 6, "every bar button has its hover square at h={h}");
        for w in &washes {
            assert_eq!(w.size(), slint::LogicalSize::new(side, side), "the hover square stays square at h={h}");
            assert_eq!(w.absolute_position().y + side / 2., h / 2., "the hover square is centred on the bar at h={h}");
        }
        let row = E::find_by_element_id(&bar, "MainToolbar::hudrow").next().expect("the status chips are mounted");
        let row_mid = row.absolute_position().y + row.size().height / 2.;
        assert!((row_mid - h / 2.).abs() <= 1., "status chips centred within 1 pt at h={h}: {row_mid}");
        let badge = E::find_by_element_id(&bar, "MainToolbar::unreadbadge").next().expect("the unread badge is mounted");
        assert_eq!(badge.absolute_position().y, (h - 16.) / 2. - 5., "badge 5 pt above the bell glyph at h={h}");
        assert!(badge.absolute_position().y + badge.size().height <= h, "badge inside the bar at h={h}");
        let bell = cells.iter().max_by(|a, b| a.absolute_position().x.total_cmp(&b.absolute_position().x)).unwrap();
        assert_eq!(bell.absolute_position().x + bell.size().width, width - 2., "the bell's cell ends 2 pt before the edge at h={h}");
    }
}

#[test]
fn full_mac_toolbar_uses_owner_actions_and_original_key_handler() {
    use slint::platform::{Key, WindowEvent as W};
    use std::{rc::Rc, cell::RefCell};
    let app = hud_app(1280., true);
    app.set_is_mac(true);
    let bar = ui::MacToolbarWindow::new().unwrap();
    bar.set_state(app.get_toolbar_state());
    let aw = app.as_weak();
    bar.on_action(move |a,x,y| { aw.unwrap().invoke_toolbar_action(a,x,y); });
    let aw = app.as_weak();
    bar.on_forward_key(move |e,p| { aw.unwrap().invoke_toolbar_key(e,p); });
    let calls = Rc::new(RefCell::new(Vec::new()));
    let c = calls.clone(); app.on_key_typed(move |s| c.borrow_mut().push(s.to_string()));
    let full = Rc::new(std::cell::Cell::new(0));
    let f = full.clone(); app.on_toggle_fullscreen(move || f.set(f.get()+1));
    bar.window().dispatch_event(W::KeyPressed { text: "f".into() });
    bar.window().dispatch_event(W::KeyReleased { text: "f".into() });
    assert_eq!(&*calls.borrow(), &["f"], "F takes the normal rebindable Rust route once");
    bar.window().dispatch_event(W::KeyPressed { text: Key::Control.into() });
    bar.window().dispatch_event(W::KeyPressed { text: Key::Meta.into() });
    bar.window().dispatch_event(W::KeyPressed { text: "f".into() });
    bar.window().dispatch_event(W::KeyReleased { text: "f".into() });
    bar.window().dispatch_event(W::KeyReleased { text: Key::Meta.into() });
    bar.window().dispatch_event(W::KeyReleased { text: Key::Control.into() });
    assert_eq!(full.get(), 1, "modifier-bearing shortcut survives cross-surface forwarding");
    assert_eq!(calls.borrow().len(), 1, "modified F does not also run plain F");
    let before = app.get_grid_open();
    bar.invoke_action("grid".into(), 0., 44.);
    assert_eq!(app.get_grid_open(), !before);
    bar.invoke_action("open".into(), 160., 44.);
    assert!(app.get_open_menu_open());
    assert_eq!(app.get_open_menu_x(), 160.);
    assert_eq!(app.get_open_menu_y(), 3.);
    app.set_confirm_kind(1);
    app.set_open_menu_open(false);
    bar.invoke_action("open".into(), 160., 44.);
    assert!(!app.get_open_menu_open(), "a stale toolbar snapshot cannot bypass the live modal guard");
}

#[test]
fn native_toolbar_inset_reflows_stage_and_keeps_popup_content_coordinates() {
    let app = hud_app(1280., true);
    app.set_mac_experiment_host(true);
    app.set_native_toolbar_inset(44.);
    hover(&app, 600., 300.);
    let stage_h = app.get_stage_h();
    for overlap in [0., 12., 44.] {
        app.set_native_toolbar_inset(overlap);
        hover(&app, 600., 300.);
        assert_eq!(app.get_content_top(), overlap);
        assert_eq!(app.get_stage_h(), stage_h + 44. - overlap, "no duplicate native toolbar row");
        app.invoke_toolbar_action("open".into(), 160., overlap);
        assert_eq!(app.get_open_menu_y(), 3.);
        app.set_open_menu_open(false);
    }
    app.set_immersive(true);
    assert_eq!(app.get_content_top(), 0.);
    app.set_immersive(false);
    app.set_mac_experiment_host(false);
    app.set_native_toolbar_inset(0.);
    assert_eq!(app.get_content_top(), 44., "ordinary Windows/Mac geometry ignores native experiment measurements");
}

// Falsifier: omit the toggle callback or persisted field. A real pointer click must
