// Falsifier: restore Settings x/y=3px, or speed x=44px/y=3px. At fractional
// desktop scales the cached panel layer then resamples all its otherwise sharp text.
#[test]
fn refinement_settings_and_speed_layers_land_on_device_pixels() {
    let app = boot_titlebar();
    app.set_motion_ui(false);
    for (name, width) in [("Settings", 360.0), ("Speed", 440.0)] {
        app.set_settings_open(name == "Settings");
        app.set_loading_open(name == "Speed");
        for sf in [1.0_f32, 1.25, 1.5, 1.75, 2.0] {
            app.set_win_sf(sf);
            for hosted in [false, true] {
                app.set_mac_experiment_host(hosted);
                app.set_native_toolbar_inset(if hosted { 38.0 } else { 0.0 });
                hover(&app, 800., 500.);
                let panel = i_slint_backend_testing::ElementHandle::find_by_element_type_name(&app, "GlassPanel")
                    .find(|e| (e.size().width - width).abs() < 0.1)
                    .unwrap_or_else(|| panic!("the actual {name} panel"));
                let p = panel.absolute_position();
                for (axis, v) in [("x", p.x), ("y", p.y)] {
                    assert!((v * sf - (v * sf).round()).abs() < 0.002,
                        "{name} {axis}={v} at scale {sf}, hosted={hosted}: fractional layer origin");
                }
            }
        }
    }
}

// Falsifiers: leave sort out of either the UI mount or cropped scheduler; omit
// hover-glass; omit the sort panel's real bounds publication or stale-crop reset.
#[test]
fn refinement_sort_menu_samples_the_same_cropped_glass() {
    let app = boot_titlebar();
    app.set_motion_ui(false);
    app.set_info_open(false); app.set_raw_open(false); app.set_compare(false);
    app.set_sort_open(true);
    hover(&app, 800., 500.);
    assert!(app.get_blur_sampler_mounted(), "sort alone must request a backdrop");
    assert!(crate::tick::menu_backdrop_active(&app), "sort must use the cropped worker path");
    let panel = i_slint_backend_testing::ElementHandle::find_by_element_type_name(&app, "GlassPanel")
        .find(|e| (e.size().width - 190.).abs() < 0.1).expect("sort panel");
    let pos=panel.absolute_position(); let size=panel.size();
    let row=i_slint_backend_testing::ElementHandle::find_by_accessible_label(&app,"Name").next().unwrap();
    assert!((row.absolute_position().x-pos.x).abs()<0.01);
    assert!((row.size().width-size.width).abs()<0.01,"sort hover fills the whole panel width");
    assert!((app.get_context_menu_x()-pos.x).abs()<0.01);
    assert!((app.get_context_menu_y()-(pos.y-app.get_content_top())).abs()<0.01);
    assert!((app.get_context_menu_w()-size.width).abs()<0.01);
    assert!((app.get_context_menu_h()-size.height).abs()<0.01);
    let bdrop=one(&app,"GlassPanel::bdrop");
    assert!(bdrop.computed_opacity()>0.99, "glass must actually sample its image");
    app.set_menu_blur_x(pos.x-10.); app.set_menu_blur_y(pos.y-app.get_content_top()-10.);
    app.set_menu_blur_w(size.width+20.); app.set_menu_blur_h(size.height+20.);
    app.set_menu_blur_ready(true);
    hover(&app,800.,500.);
    assert!((bdrop.size().width-(size.width+20.)).abs()<0.01, "sample the cropped texture, not whole content");
    app.set_sort_open(false); hover(&app,800.,500.);
    assert!(!app.get_menu_blur_ready(), "a later menu must not inherit crop readiness");
}

