// Owner-approved View only now permits browsing a verified partial list; edits
// remain modal-gated. Falsifier: keep arrows/wheel on popup-open rather than the
// inspection/navigation gate, or let real dialogs/menus fall through that gate.
#[test]
fn refinement_view_only_browses_neighbours_but_true_popups_still_block() {
    use std::{cell::Cell,rc::Rc};
    use slint::platform::Key;
    let app=boot_titlebar(); app.set_motion_ui(false); app.set_empty_state(false);
    app.set_opening_photo(true); app.set_photo_ready(true); app.set_photo_open_edits(false);
    app.set_grid_open(false); app.set_film_visible(false); app.set_raw_open(false); app.set_info_open(false);
    app.set_count_all(21); app.set_cur_idx(10); app.set_wheel_nav(true);
    let hits=Rc::new(Cell::new(0));
    let h=hits.clone(); app.on_navigate(move |_|h.set(h.get()+1));
    let h=hits.clone(); app.on_navigate_step(move |_|h.set(h.get()+1));
    let h=hits.clone(); app.on_sel_jump(move |_|h.set(h.get()+1));
    hover(&app,700.,400.);
    assert!(app.get_modal_open(),"ratings/rotation/file action gates remain closed");
    assert_eq!(app.invoke_sel_gesture_kind(true,false),-1,"no partial-list multi-selection");
    key(&app,Key::RightArrow); key(&app,Key::LeftArrow);
    key(&app,Key::Home); key(&app,Key::End); wheel(&app,700.,400.,-40.);
    assert_eq!(hits.get(),3,"arrows/wheel browse before full scan; Home/End still need real folder endpoints");
    assert!(app.invoke_neighbour_browse_allowed(false,false));
    assert!(!app.invoke_neighbour_browse_allowed(true,false));
    assert!(!app.invoke_neighbour_browse_allowed(false,true));
    for popup in 0..4 {
        match popup { 0=>app.set_settings_open(true),1=>app.set_confirm_kind(1),
            2=>app.set_sort_open(true),_=>app.set_welcome_open(true) }
        i_slint_core::properties::ChangeTracker::run_change_handlers();
        let before=hits.get(); key(&app,Key::RightArrow); wheel(&app,700.,400.,-40.);
        assert_eq!(hits.get(),before,"popup {popup} keeps navigation blocked");
        app.set_settings_open(false); app.set_confirm_kind(0); app.set_sort_open(false); app.set_welcome_open(false);
    }
}

/// Removing the overlay wait term, restoring grid-arrow clamping or hiding pending
/// tiles reproduces the silent temporary end and makes this regression fail.
#[test]
fn batch_boundary_loading_is_visible_and_placeholder_clicks_are_not_photo_actions() {
    use crate::photo_open;
    use i_slint_backend_testing::ElementHandle as E;
    use i_slint_core::items::PointerEventButton;
    use slint::platform::Key;
    use std::{cell::RefCell, rc::Rc};
    let app = boot_titlebar();
    app.set_motion_ui(false); app.set_empty_state(false);
    app.set_opening_photo(true); app.set_photo_ready(true);
    app.set_opening_before(true); app.set_opening_after(true);
    app.set_count_all(21); app.set_cur_idx(20); app.set_grid_open(true);
    app.set_grid_cols(2); app.set_grid_virtual_h(300.); app.set_grid_win_y(8.);
    let pending = photo_open::pending_tile(21, 21, (true, true));
    app.set_grid_items(slint::ModelRc::new(slint::VecModel::from(vec![pending])));
    let calls = Rc::new(RefCell::new(Vec::new()));
    let seen = calls.clone(); app.on_sel_jump(move |i| seen.borrow_mut().push(i));
    let rows = Rc::new(std::cell::Cell::new(0)); let seen = rows.clone();
    app.on_grid_boundary_step(move |direction| seen.set(direction));
    let edits = Rc::new(std::cell::Cell::new(0));
    let e = edits.clone(); app.on_sel_toggle_flag(move |_,_| e.set(e.get()+1));
    let e = edits.clone(); app.on_ctx_populate(move |_| e.set(e.get()+1));
    hover(&app, 700., 400.);
    assert!(!app.get_opening_boundary_wait());
    assert!(E::find_by_element_id(&app,"MainWindow::folder-scan-overlay").next().is_none());
    key(&app, Key::DownArrow);
    assert_eq!(rows.get(), 1, "grid arrows retain row intent separately from photo clicks");
    assert!(calls.borrow().is_empty(), "a row wait must not jump to the batch edge");
    let tile = E::find_by_element_id(&app,"GridThumb::jta").next().unwrap();
    tile.mock_single_click(PointerEventButton::Left);
    tile.mock_single_click(PointerEventButton::Right);
    assert_eq!(*calls.borrow(), vec![21], "placeholder has a navigation target, no photo identity");
    assert_eq!(edits.get(),0);
    assert!(!app.get_ctx_open());
    assert!(photo_open::hold_boundary(&app,21,21));
    assert!(photo_open::hold_boundary(&app,25,21));
    assert_eq!(app.get_opening_wait_dir(),1,"repeats retain one direction, not a step count");
    hover(&app,700.,400.);
    assert!(app.get_opening_boundary_wait());
    assert!(E::find_by_element_id(&app,"MainWindow::folder-scan-overlay").next().is_some());
    assert!(app.get_photo_ready(),"loading feedback must not delay scan promotion");
    assert!(!photo_open::hold_boundary(&app,19,21));
    assert!(!app.get_opening_boundary_wait(),"browsing back cancels the wait");
    app.set_opening_photo(false);
    assert!(!photo_open::hold_boundary(&app,21,21));
}

#[test]
fn batch_boundary_grid_keys_keep_the_original_photo_and_row_width() {
    use crate::photo_open;
    use slint::platform::Key;
    let app = boot();
    app.set_opening_photo(true); app.set_photo_ready(true); app.set_grid_open(true);
    app.set_opening_before(true); app.set_opening_after(true);
    app.set_count_all(21); app.set_cur_idx(18); app.set_grid_cols(4);
    let weak = app.as_weak();
    app.on_grid_boundary_step(move |direction| {
        let a = weak.upgrade().unwrap();
        assert_eq!(photo_open::grid_row_navigation(&a, a.get_cur_idx() as usize,
            a.get_count_all() as usize, direction), None);
    });
    app.on_sel_jump(|_| panic!("unfinished grid row must keep the original photo, not jump to its edge"));
    key(&app, Key::DownArrow);
    assert_eq!(app.get_cur_idx(),18);
    assert_eq!(app.get_opening_wait_dir(),4);
    app.set_grid_cols(2); key(&app,Key::DownArrow);
    assert_eq!(app.get_opening_wait_dir(),4,"a smaller row fitting in the batch must not cancel the wait");
    app.set_grid_cols(5); key(&app,Key::DownArrow);
    assert_eq!(app.get_opening_wait_dir(),4,"repeat/resizing keeps the originally requested row");
    // The current photo has moved from batch index 18 to full-folder index 38.
    assert_eq!(photo_open::promoted_navigation(38,100,app.get_opening_wait_dir(),false,(false,false)),(42,0));
    app.set_grid_cols(4);
    assert_eq!(photo_open::grid_row_navigation(&app,18,21,-1),Some(14));
    assert_eq!(app.get_opening_wait_dir(),0,"reverse movement cancels the pending Down");
    app.set_cur_idx(2); key(&app,Key::UpArrow);
    assert_eq!(app.get_cur_idx(),2); assert_eq!(app.get_opening_wait_dir(),-4);
    assert_eq!(photo_open::promoted_navigation(38,100,-4,false,(false,false)),(34,0));
}

// Owner-approved disabled thumbnail actions. Falsifier: let badge callbacks fire
// during View only, or allow a refused compare drag to create/drop its overlay.
#[test]
fn refinement_unavailable_thumbnail_actions_do_not_swallow_plain_browsing() {
    use std::{cell::Cell,rc::Rc};
    use i_slint_core::items::PointerEventButton;
    for review in [false,true] {
        let app=boot_titlebar(); app.set_motion_ui(false); app.set_empty_state(false);
        app.set_opening_photo(true); app.set_photo_open_edits(false); app.set_photo_ready(true);
        app.set_info_open(false); app.set_raw_open(false); app.set_film_visible(false);
        app.set_count_all(21); app.set_cur_idx(10);
        let item=ui::FilmItem { idx:0,name:"Test photo".into(),badge:"JPG".into(),
            valid:true,flag:true,reject:true,..Default::default() };
        if review {
            app.set_grid_open(false);
            review_panel(&app,slint::ModelRc::new(slint::VecModel::from(vec![ui::SelTileRow {
                a:item,has_b:false,..Default::default()
            }])));
        } else {
            app.set_grid_open(true); app.set_grid_cols(3); app.set_grid_virtual_h(88.);
            app.set_grid_items(slint::ModelRc::new(slint::VecModel::from(vec![item])));
        }
        let edits=Rc::new(Cell::new(0)); let jumps=Rc::new(Cell::new(0)); let drops=Rc::new(Cell::new(0));
        let e=edits.clone(); app.on_sel_toggle_flag(move |_,_|e.set(e.get()+1));
        let e=edits.clone(); app.on_sel_toggle_reject(move |_,_|e.set(e.get()+1));
        let e=edits.clone(); app.on_sel_set_rating(move |_,_,_|e.set(e.get()+1));
        let j=jumps.clone(); app.on_sel_jump(move |_|j.set(j.get()+1));
        let d=drops.clone(); app.on_sel_to_compare(move |_,_|d.set(d.get()+1));
        hover(&app,800.,500.);
        let ids=if review {["SelTile::fbta","SelTile::rbta"]} else {["GridThumb::fta","GridThumb::rta"]};
        for id in ids { one(&app,id).mock_single_click(PointerEventButton::Left); }
        assert_eq!(edits.get(),0,"disabled thumbnail edits still swallow the click, review={review}");
        assert_eq!(jumps.get(),0,"a disabled badge click is not a thumbnail jump");
        let tile=one(&app,if review {"SelTile::jta"} else {"GridThumb::jta"});
        tile.mock_single_click(PointerEventButton::Left);
        assert_eq!(jumps.get(),1,"plain browsing remains active, review={review}");
        tile.mock_drag(slint::LogicalPosition::new(850.,350.),PointerEventButton::Left);
        assert_eq!(drops.get(),0,"no unavailable compare action offered during discovery");
        assert!(!app.get_sel_dragging());
        app.set_photo_open_edits(true);
        assert!(!app.get_sel_affordance_live(),"early edits do not promise unavailable multi-selection");
        for id in ids { one(&app,id).mock_single_click(PointerEventButton::Left); }
        assert_eq!(edits.get(),2,"approved early-edit mode retains its actions");
    }
}

// Falsifiers: default On; drop the saved getter/callback; apply the preference before
// the registry operation succeeds. Exercise the real UI and preference callback.
#[test]
fn distinct_raw_icons_default_off_toggle_save_and_failure() {
    use i_slint_backend_testing::ElementHandle as E;
    let old: crate::support::Settings = serde_json::from_str("{}").unwrap();
    assert!(!old.distinct_raw_icons);
    let app = boot();
    app.window().set_size(slint::LogicalSize::new(1200., 9000.));
    app.set_motion_ui(false);
    app.set_settings_open(true);
    app.set_file_assoc_visible(true);
    app.set_assoc_mac_mode(false);
    let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
    let fail = std::rc::Rc::new(std::cell::Cell::new(false));
    let (record, failure) = (calls.clone(), fail.clone());
    crate::file_icons::wire_preference(&app, move |value| {
        record.borrow_mut().push(value);
        if failure.get() && value { Err(std::io::Error::other("fixture denied")) } else { Ok(()) }
    });
    hover(&app, 600., 300.);
    assert!(!app.get_distinct_raw_icons());
    for enabled in [true, false] {
        let row = E::find_by_element_id(&app, "MainWindow::raw-icon-option").next().expect("Windows file icon preference");
        let p = row.absolute_position(); let size = row.size();
        click(&app, p.x + size.width / 2., p.y + size.height / 2., i_slint_core::items::PointerEventButton::Left);
        assert_eq!(app.get_distinct_raw_icons(), enabled);
        let saved = crate::support::build_settings(&app, true, true, &std::collections::HashMap::new(),
            "", "", &[], &[], "name.asc", &[], &[], &std::collections::BTreeMap::new(),
            false, crate::support::INFO_VIEW_STANDARD);
        let loaded: crate::support::Settings = serde_json::from_str(&serde_json::to_string(&saved).unwrap()).unwrap();
        assert_eq!(loaded.distinct_raw_icons, enabled);
    }
    assert_eq!(*calls.borrow(), [true, false]);
    fail.set(true);
    app.invoke_distinct_raw_icons_toggled();
    assert!(!app.get_distinct_raw_icons());
    assert!(app.get_assoc_status().contains("fixture denied"));
    assert_eq!(*calls.borrow(), [true, false, true, false]);
    app.set_assoc_mac_mode(true);
    hover(&app, 600., 300.);
    assert!(E::find_by_element_id(&app, "MainWindow::raw-icon-option").next().is_none(), "Windows-only option is unmounted on Mac");
}

// Falsifiers: disconnect the version hit area, omit modal/key gates, or dismiss the
// underlying Settings on Escape. Use the real card, input dispatch and link callback.
#[test]
fn about_card_version_links_modal_gates_and_dismissal() {
    use std::{cell::{Cell, RefCell}, rc::Rc};
    use i_slint_backend_testing::ElementHandle as E;
    use i_slint_core::items::PointerEventButton::Left;
    for mac in [false, true] {
        let app = boot_titlebar(); app.set_motion_ui(false);
        app.window().set_size(slint::LogicalSize::new(1200., 9000.));
        app.set_native_window_controls(mac); app.set_app_version("1.0.9".into());
        app.set_empty_state(false); app.set_photo_ready(true); app.set_count_all(6);
        let calls = Rc::new(RefCell::new(Vec::new())); let c = calls.clone();
        crate::about::wire(&app, move |url| { c.borrow_mut().push(url.to_owned()); Ok(()) });
        app.invoke_about_link_requested(0); assert!(calls.borrow().is_empty(), "closed card cannot launch links");
        app.set_settings_open(true); hover(&app, 600., 300.);
        let version = E::find_by_element_id(&app, "MainWindow::about-version-hit").next().unwrap();
        let p=version.absolute_position(); let size=version.size();
        click(&app,p.x+size.width/2.,p.y+size.height/2.,Left);
        assert!(app.get_about_open()); assert!(app.get_settings_open());
        for (id, expected) in [("AboutCard::about-github",crate::about::REPOSITORY),
                               ("AboutCard::about-instagram","https://www.instagram.com/hwuphoto/"),
                               ("AboutCard::about-linkedin","https://www.linkedin.com/in/hancheng-wu-325794321")] {
            let row=E::find_by_element_id(&app,id).next().unwrap(); let p=row.absolute_position(); let size=row.size();
            click(&app,p.x+size.width/2.,p.y+size.height/2.,Left);
            assert_eq!(calls.borrow().last().map(String::as_str),Some(expected));
        }
        app.invoke_about_link_requested(999); assert_eq!(calls.borrow().len(),3);
        key(&app,slint::platform::Key::Escape);
        assert!(!app.get_about_open()); assert!(app.get_settings_open(), "Escape returns to Settings");
        app.invoke_show_about(); hover(&app,600.,300.);
        let close=E::find_by_element_id(&app,"AboutCard::about-x").next().unwrap(); let p=close.absolute_position(); let size=close.size();
        click(&app,p.x+size.width/2.,p.y+size.height/2.,Left); assert!(!app.get_about_open());
        app.invoke_show_about(); hover(&app,600.,300.);
        click(&app,20.,app.get_content_top()+20.,Left);
        assert!(!app.get_about_open()); assert!(app.get_settings_open());
        // About's own gates must hold even if the panel underneath is no longer open.
        app.set_settings_open(false); app.invoke_show_about(); hover(&app,600.,300.);
        assert!(app.get_dialog_open() && app.get_modal_blocking() && app.get_inspection_blocked());
        let hits=Rc::new(Cell::new(0)); let h=hits.clone(); app.on_navigate(move |_|h.set(h.get()+1));
        let h=hits.clone(); app.on_navigate_step(move |_|h.set(h.get()+1));
        let h=hits.clone(); app.on_key_typed(move |_|h.set(h.get()+1));
        let h=hits.clone(); app.on_escape_pressed(move ||h.set(h.get()+1));
        app.set_capture_armed(true);
        key(&app,slint::platform::Key::RightArrow); key(&app,slint::platform::Key::F12);
        app.invoke_toolbar_action("settings".into(),0.,0.);
        assert!(!app.get_settings_open()); assert_eq!(hits.get(),0);
        key(&app,slint::platform::Key::Escape); assert!(!app.get_about_open()); assert_eq!(hits.get(),0);
    }
}

