// Public-release regression: a stretched left slot centres the control beside Welcome,
// not against Settings. Removing the independent anchor must fail this rendered geometry.
#[test]
fn public_release_footer_left_aligns_about_and_keeps_welcome_separate() {
    use i_slint_backend_testing::ElementHandle as E;
    for sf in [1.0_f32, 1.25, 1.5, 2.0] {
      for version in ["1.0.11", "1.0.11-mac-full04"] {
        let app=boot_titlebar(); app.set_motion_ui(false); app.set_win_sf(sf); app.set_app_version(version.into());
        app.window().set_size(slint::LogicalSize::new(650.,9000.));
        app.set_settings_open(true); hover(&app,600.,300.);
        let hit=E::find_by_element_id(&app,"MainWindow::about-version-hit").next().unwrap();
        let body=E::find_by_element_id(&app,"MainWindow::setflick").next().unwrap();
        assert!((hit.absolute_position().x-body.absolute_position().x).abs()<1., "left edge matches settings content at {sf}");
        let welcome=E::find_by_element_id(&app,"MainWindow::about-welcome-hit").next().unwrap();
        // Falsifier: remove the long-label clamp; the diagnostic suffix crowds Welcome.
        assert!(hit.absolute_position().x+hit.size().width+8.<=welcome.absolute_position().x+0.01,"8 px gap for {version} at {sf}");
        click(&app,welcome.absolute_position().x+welcome.size().width/2.,welcome.absolute_position().y+welcome.size().height/2.,i_slint_core::items::PointerEventButton::Left);
        assert!(app.get_welcome_open()); assert!(!app.get_settings_open());
      }
    }
}

#[test]
fn welcome_associations_apply_all_uses_existing_platform_paths_and_available_formats() {
    use std::{cell::Cell,rc::Rc};
    use i_slint_backend_testing::ElementHandle as E;
    use i_slint_core::items::PointerEventButton::Left;
    for mac in [false,true] {
        for heic in [false,true] {
            let app=boot(); app.set_motion_ui(false); app.set_welcome_open(true);
            app.window().set_size(slint::LogicalSize::new(1400.,1400.));
            app.set_file_assoc_visible(true); app.set_assoc_mac_mode(mac);
            app.set_assoc_heic_avail(heic);
            app.set_assoc_jpeg(false); app.set_assoc_raw(false);
            let windows=Rc::new(Cell::new(0)); let w=windows.clone();
            app.on_assoc_apply(move || w.set(w.get()+1));
            let apple=Rc::new(Cell::new(-1)); let m=apple.clone();
            app.on_assoc_prompt_choice(move |choice|m.set(choice));
            hover(&app,700.,700.);
            let button=E::find_by_element_id(&app,"MainWindow::welcome-assoc-all").next().unwrap();
            let pos=button.absolute_position(); let size=button.size();
            click(&app,pos.x+size.width/2.,pos.y+size.height/2.,Left);
            if mac {
                assert_eq!(apple.get(),2); assert_eq!(windows.get(),0);
            } else {
                assert_eq!(windows.get(),1); assert_eq!(apple.get(),-1);
                assert!(app.get_assoc_jpeg() && app.get_assoc_png() && app.get_assoc_tiff()
                    && app.get_assoc_webp() && app.get_assoc_gif() && app.get_assoc_bmp()
                    && app.get_assoc_jxl() && app.get_assoc_raw());
                assert_eq!(app.get_assoc_heic(),heic,"no registration claim for an unavailable codec");
            }
            assert!(app.get_welcome_open(),"one-click setup keeps the welcome card usable");
        }
    }
}

