// Falsifier: leave the birth default off; a real stage wheel event zooms instead of browsing.
#[test]
fn release_ui_first_stage_wheel_browses_and_opt_out_still_zooms() {
    use std::{cell::Cell, rc::Rc};
    let app = boot_titlebar();
    app.set_motion_ui(false);
    app.set_empty_state(false);
    app.set_photo_ready(true);
    app.set_grid_open(false);
    app.set_film_visible(false);
    app.set_raw_open(false);
    app.set_info_open(false);
    app.set_count_all(5);
    app.set_cur_idx(2);
    let nav = Rc::new(Cell::new(0));
    let zoom = Rc::new(Cell::new(0));
    let n = nav.clone();
    app.on_navigate_step(move |_| n.set(n.get() + 1));
    let z = zoom.clone();
    app.on_zoom_at(move |_, _, _| z.set(z.get() + 1));
    hover(&app, 700., 400.);
    wheel(&app, 700., 400., -40.);
    assert_eq!((nav.get(), zoom.get()), (1, 0));
    // Slint maps physical Command to Control on Mac; this exercises the shared modifier arm.
    use slint::platform::{Key, WindowEvent};
    for is_mac in [false, true] {
        app.set_is_mac(is_mac);
        let before = (nav.get(), zoom.get());
        app.window().dispatch_event(WindowEvent::KeyPressed {
            text: Key::Control.into(),
        });
        wheel(&app, 700., 400., -40.);
        app.window().dispatch_event(WindowEvent::KeyReleased {
            text: Key::Control.into(),
        });
        assert_eq!((nav.get(), zoom.get()), (before.0, before.1 + 1));
    }
    wheel(&app, 700., 400., -40.);
    assert_eq!(nav.get(), 2, "releasing the modifier restores browsing");
    let before = zoom.get();
    app.set_wheel_nav(false);
    wheel(&app, 700., 400., -40.);
    assert_eq!((nav.get(), zoom.get()), (2, before + 1));
}

// Falsifier: publish source facts only when current != last_seen, or guess from the filename.
#[test]
fn release_ui_source_format_refreshes_without_navigation() {
    use falcon_decode::{Shot, SrcKind};
    use std::{
        cell::{Cell, RefCell},
        time::Instant,
    };
    let app = boot();
    app.set_motion_ui(false);
    app.set_empty_state(false);
    app.set_raw_open(true);
    let mut shot = Shot {
        id: 0,
        name: "same".into(),
        has_raw: true,
        has_jpg: true,
        raw: Some("same.RAF".into()),
        jpg: Some("same.JPG".into()),
        kind: SrcKind::Png,
        sniffed: Some(SrcKind::Png),
        cloud_placeholder: false,
    };
    let update = |shots: &[Shot]| {
        crate::tick::step_bookkeeping(
            &app,
            Instant::now(),
            &RefCell::new(0),
            &RefCell::new(0),
            &RefCell::new(Instant::now()),
            &RefCell::new(None),
            &RefCell::new(Vec::new()),
            shots,
            &RefCell::new(vec![0]),
            &RefCell::new(vec![0]),
            &Cell::new(false),
            &Cell::new(None),
        );
        hover(&app, 700., 400.);
    };
    let visible = |text| {
        i_slint_backend_testing::ElementHandle::find_by_accessible_label(&app, text)
            .next()
            .is_some()
    };
    update(&[shot.clone()]);
    assert_eq!(app.get_cur_finished_format().as_str(), "PNG");
    assert!(visible("PNG"));
    shot.kind = SrcKind::Heic;
    shot.sniffed = Some(SrcKind::Heic);
    update(&[shot.clone()]);
    assert_eq!(app.get_cur_finished_format().as_str(), "HEIC");
    assert!(visible("HEIC"));
    assert_eq!(
        crate::support::ctx_populate_fields(Some(&shot), &[]).copy_fmt_label,
        "Copy HEIC"
    );
    shot.kind = SrcKind::Jpeg;
    shot.has_jpg = false;
    shot.jpg = Some("undecodable.AVIF".into());
    update(&[shot]);
    assert!(!app.get_cur_has_finished());
    assert!(visible("Preview"));
    update(&[]);
    assert!(!app.get_cur_has_raw());
    assert_eq!(app.get_cur_finished_format().as_str(), "Image");
}

