/// Grid review R1 (re-check): Compare with both halves free and "Never browse onto a blank photo"
/// on, A at the top of the folder and B far down. The grid asked for B's next two photos while
/// their rows were on screen, then scrolled away: retirement keeps 501 (B's next) but drops 502.
/// The first wheel step lands on 501; the SECOND needs 502, which nothing else would ever ask for
/// again. The held step asks for it, and the browse goes on.
/// FALSIFIER: return at the top of `tick::ask_compare_target` and the second step stays held.
#[test]
fn a_compare_browse_survives_two_steps_after_a_grid_scroll() {
    use crate::tick::{
        drain_thumbs, feed_visible_thumb, step_compare_browse_advance, step_retire_thumbs,
        thumb_keep_around, FastCache, NavKind, ThumbAsk, ThumbDrop,
    };
    use std::cell::{Cell, RefCell};
    use std::collections::HashSet;
    use std::sync::Mutex;
    use std::time::{Duration, Instant};

    let app = boot();
    app.set_scrub_fps(30.0);
    app.set_zoom(1.0);
    app.set_zoom_always_sharp(false);
    app.set_scrub_wait_cache(true);
    app.set_compare(true);
    app.set_pin_a(false);
    app.set_pin_b(false);
    app.set_cmp_focus(0);
    let shots: Vec<falcon_decode::Shot> = (0..600)
        .map(|i| falcon_decode::Shot {
            id: i,
            name: format!("IMG_{i:04}"),
            has_raw: false,
            has_jpg: true,
            raw: None,
            jpg: Some(std::path::PathBuf::from("C:/f/a.jpg")),
            kind: falcon_decode::SrcKind::Jpeg,
            cloud_placeholder: false,
            sniffed: None,
        })
        .collect();
    let film = crate::Film::new();
    let rot = crate::RotState::new(true);
    let (tx, rx) = std::sync::mpsc::channel();
    let mut queue = crate::support::ThumbQueue::new(rx);
    let (res_tx, res_rx) = std::sync::mpsc::channel::<ThumbDrop>();
    let tg = Cell::new(0u64);
    let fastc = RefCell::new(FastCache::new());
    let ffail: Mutex<HashSet<(u64, usize)>> = Mutex::new(HashSet::new());
    // A's side is the focused half: the filmstrip and preview prefetch already cover it.
    for i in 1..=3 {
        film.thumbs.borrow_mut().insert(i, (slint::Image::from_rgba8(slint::SharedPixelBuffer::new(1, 1)), 0));
    }
    // Every request the workers take now lands (the drain the tick runs).
    let land = |queue: &mut crate::support::ThumbQueue| {
        while let Some(r) = queue.try_take() {
            res_tx.send((r.idx, r.gen, vec![255; 4], 1, 1, 0, 0, 0)).unwrap();
        }
        drain_thumbs(&res_rx, &film, &rot, &tg, 0, 0, 0, 0);
    };
    let keep = |a: usize, b: usize| thumb_keep_around(a, Some((a, b)));

    film.pinned.borrow_mut().extend(495..510); // the grid dock shows B's rows
    {
        let mut tp = film.pending.borrow_mut();
        for i in [501, 502] {
            feed_visible_thumb(&tx, &mut tp, i, 0, 0, crate::GRID_FEED_PENDING_MAX);
        }
    }
    step_retire_thumbs(&tx, &film, (0, 5), &keep(0, 500), 0, &tg);
    film.pinned.borrow_mut().clear(); // the dock scrolls away before either decode starts
    assert_eq!(step_retire_thumbs(&tx, &film, (0, 5), &keep(0, 500), 0, &tg), 1, "502 retires; 501 is kept");
    land(&mut queue);

    let compare = Cell::new(true);
    let a_idx = Cell::new(0usize);
    let b_idx = Cell::new(500usize);
    let cur = RefCell::new(0usize);
    let ff = Cell::new(false);
    let nkind = Cell::new(NavKind::Absolute);
    let notch = || {
        let now = Instant::now();
        let accum = Cell::new(1i32);
        let wheel_at = RefCell::new(now);
        let wheel_adv = RefCell::new(now - Duration::from_millis(100));
        let last_motion = RefCell::new(now);
        step_compare_browse_advance(
            &app, now, shots.len(), 0, &compare, &accum, &wheel_at, &wheel_adv, &last_motion,
            &a_idx, &b_idx, &cur, &ff, &nkind, &shots, &film.thumbs, &fastc, &film.failed, &ffail,
            crate::support::EfficiencyLimits::RELEASED,
            Some(ThumbAsk { tx: &tx, film: &film, rot: &rot }),
        );
        (a_idx.get(), b_idx.get())
    };
    assert_eq!(notch(), (1, 501), "the first step lands on B's kept next photo");
    assert_eq!(notch(), (1, 501), "the second step waits: 502 was retired");
    assert!(film.pending.borrow().contains(&502), "the held step asked for 502 again");
    assert_eq!(step_retire_thumbs(&tx, &film, (0, 5), &keep(1, 501), 0, &tg), 0, "and it is protected now");
    land(&mut queue);
    assert_eq!(notch(), (2, 502), "its thumbnail lands and the browse goes on");
    app.set_compare(false);
}

// Settings reuses the existing bar without taking width from controls. Removing its mount
// fails the first geometry lookup; disconnecting seek fails the footer/top assertions.
#[test]
fn settings_scroll_bar_fits_padding_and_seeks_the_body() {
    use i_slint_backend_testing::ElementHandle as E;
    use i_slint_core::items::PointerEventButton::Left;
    let app = boot();
    app.set_motion_ui(false);
    app.set_welcome_open(false);
    app.set_grid_open(false);
    app.set_sel_open(false);
    app.set_settings_open(true);
    let element = |id: &str| E::find_by_element_id(&app, id).next().unwrap_or_else(|| panic!("{id}"));
    for (width, height, sf) in [(960., 1080., 1.), (768., 864., 1.25), (640., 720., 1.5)] {
        app.window().set_size(slint::LogicalSize::new(width, height));
        app.set_win_sf(sf);
        for inset in [0., 38.25] {
            app.set_mac_experiment_host(inset > 0.);
            app.set_native_toolbar_inset(inset);
            hover(&app, width - 20., 400.);
            let panel = element("MainWindow::setbox");
            let flick = element("MainWindow::setflick");
            let band = element("MiniVBar::barta"); // zero-offset child: actual hit band
            let (pp, ps) = (panel.absolute_position(), panel.size());
            let (fp, fs) = (flick.absolute_position(), flick.size());
            let (bp, bs) = (band.absolute_position(), band.size());
            assert!((ps.width - 360.).abs() < 0.01 && (fs.width - 320.).abs() < 0.01,
                "Settings and controls retain their existing widths");
            assert!((bs.width - 8.).abs() < 0.01);
            assert!(bp.x - (fp.x + fs.width) >= 5., "bar must not overlap controls");
            assert!(pp.x + ps.width - (bp.x + bs.width) >= 5., "bar fits existing right padding");
            assert!((bp.y - fp.y).abs() <= 1. / sf && (bs.height - fs.height).abs() <= 1. / sf);
            for edge in [bp.x, bp.y, bp.y + bs.height] {
                assert!((edge * sf - (edge * sf).round()).abs() < 0.002,
                    "bar edge {edge} must be on device pixels at {sf}, inset {inset}");
            }
        }
    }
    app.window().set_size(slint::LogicalSize::new(960., 720.));
    app.set_win_sf(1.);
    app.set_mac_experiment_host(false);
    app.set_native_toolbar_inset(0.);
    hover(&app, 800., 400.);
    let flick = element("MainWindow::setflick");
    let body = element("MainWindow::body");
    let band = element("MiniVBar::barta");
    let thumb = element("MiniVBar::thumb");
    let (fp, fs) = (flick.absolute_position(), flick.size());
    let (bp, bs) = (band.absolute_position(), band.size());
    let start = body.absolute_position().y;
    let initial_thumb = thumb.absolute_position().y;
    assert!(body.size().height > fs.height + 100., "fixture genuinely scrolls");
    let settle = || {
        i_slint_backend_testing::mock_elapsed_time(std::time::Duration::from_millis(200));
        hover(&app, 800., 400.);
    };
    wheel(&app, fp.x + fs.width / 2., fp.y + 80., -120.);
    settle();
    assert!(body.absolute_position().y < start - 1., "wheel still scrolls Settings");
    assert!(thumb.absolute_position().y > initial_thumb, "thumb follows wheel scrolling");
    let x = bp.x + bs.width / 2.;
    drag(&app, &[(x, bp.y + bs.height / 2.), (x, bp.y + bs.height - 1.)]);
    settle();
    assert!((body.absolute_position().y + body.size().height - fp.y - fs.height).abs() < 1.,
        "dragging down reaches the real end of the scroll body");
    // The footer's actual button centre must remain in the viewport and reachable.
    let footer = element("MainWindow::about-version-hit");
    let footer_centre = footer.absolute_position().y + footer.size().height / 2.;
    assert!(footer_centre >= fp.y && footer_centre <= fp.y + fs.height,
        "dragging down reaches footer: footer={:?}/{:?}, viewport={fp:?}/{fs:?}, body={:?}/{:?}, band={bp:?}/{bs:?}, thumb={:?}/{:?}",
        footer.absolute_position(), footer.size(), body.absolute_position(), body.size(),
        thumb.absolute_position(), thumb.size());
    assert!(app.get_settings_open() && !app.get_welcome_open(), "bar clicks stay in Settings");
    click(&app, x, bp.y + 1., Left);
    settle();
    assert!((body.absolute_position().y - start).abs() < 1., "top click returns to the first section");
    app.window().set_size(slint::LogicalSize::new(1200., 9000.));
    settle();
    assert!(body.size().height < flick.size().height, "tall fixture fits the complete body");
    assert_eq!(E::find_by_element_type_name(&app, "MiniVBar").count(), 0,
        "no bar when Settings needs no scrolling");
}
